impl WidthPolicy {
    fn resolve(self, viewport: f64) -> Result<f64, LayoutError> {
        let width = match self {
            Self::Fixed(w) if positive(w) => w,
            Self::ViewportFraction(f) if f.is_finite() && f > 0.0 && f <= MAX_COORD => {
