1	//! Nested logical configuration: all source/evaluation/binding work is worker-owned.
2	use flux_config::{Config, ConfigCoordinator, HelperLimits};
3	use flux_input::{BindingSet, UnmappedPolicy};
4	use std::{
5	    path::PathBuf,
6	    sync::{Arc, Condvar, Mutex},
7	    thread::JoinHandle,
8	};
9	use xkbcommon::xkb;
10	
11	type Failure = &'static str;
12	struct Prepared {
13	    desired: Config,
14	    bindings: BindingSet,
15	    default_width: flux_layout::WidthPolicy,
16	}
17	// Retired schema/tables and replaced live-model storage are dropped on the worker.
18	// Temporary layout clones in reconfigure/validation still drop on dispatch.
19	struct Retired {
20	    _desired: Option<Config>,
21	    _bindings: Option<BindingSet>,
22	    _layout: Option<flux_layout::Layout>,
23	}
24	#[derive(Default)]
25	struct Control {
26	    latest: u64,
27	    pending: Option<(u64, PathBuf)>,
28	    evaluation_ready: bool,
29	    completion: Option<(u64, Result<Prepared, Failure>)>,
30	    retired: Option<Retired>,
31	    closed: bool,
32	}
33	#[derive(Default)]
34	struct Shared {
35	    control: Mutex<Control>,
36	    changed: Condvar,
37	}
38	pub struct RuntimeConfig {
39	    source: PathBuf,
40	    shared: Arc<Shared>,
41	    worker: Option<JoinHandle<()>>,
42	    desired: Option<Config>,
43	    applied: Option<u64>,
44	    status: &'static str,
45	    last_error: Option<Failure>,
46	}
47	impl RuntimeConfig {
48	    fn new(
49	        source: PathBuf,
50	        helper: PathBuf,
51	        keymap: String,
52	        ping: calloop::ping::Ping,
53	    ) -> std::io::Result<Self> {
54	        let shared = Arc::new(Shared::default());
55	        let notified = shared.clone();
56	        let coordinator = ConfigCoordinator::new(helper, HelperLimits::default(), move || {
57	            notified
58	                .control
59	                .lock()
60	                .unwrap_or_else(|e| e.into_inner())
61	                .evaluation_ready = true;
62	            notified.changed.notify_one();
63	        })?;
64	        let control = shared.clone();
65	        let worker = std::thread::Builder::new()
66	            .name("flux-config-prepare".into())
67	            .spawn(move || run_worker(control, coordinator, keymap, ping))?;
68	        Ok(Self {
69	            source,
70	            shared,
71	            worker: Some(worker),
72	            desired: None,
73	            applied: None,
74	            status: "pending",
75	            last_error: None,
76	        })
77	    }
78	    fn request(&mut self) -> Result<u64, Failure> {
79	        let mut c = self
80	            .shared
81	            .control
82	            .lock()
83	            .unwrap_or_else(|e| e.into_inner());
84	        if c.closed || self.worker.as_ref().is_none_or(|w| w.is_finished()) {
85	            return Err("configuration worker is unavailable");
86	        }
87	        let generation = c
88	            .latest
89	            .checked_add(1)
90	            .ok_or("configuration generation exhausted")?;
91	        c.latest = generation;
92	        // Only a bounded path is replaced here. Old large completions stay on
93	        // the worker until it observes the superseding request.
94	        c.pending = Some((generation, self.source.clone()));
95	        self.status = "pending";
96	        self.last_error = None;
97	        self.shared.changed.notify_one();
98	        Ok(generation)
99	    }
100	    fn completion(&mut self) -> Option<(u64, Result<Prepared, Failure>)> {
101	        let mut c = self
102	            .shared
103	            .control
104	            .lock()
105	            .unwrap_or_else(|e| e.into_inner());
106	        if self.status != "failed" && self.worker.as_ref().is_none_or(|w| w.is_finished()) {
107	            return Some((c.latest, Err("configuration preparation worker stopped")));
108	        }
109	        if c.retired.is_some() || c.completion.as_ref()?.0 != c.latest {
110	            return None;
111	        }
112	        c.completion.take()
113	    }
114	    fn retire(&self, value: Retired) {
115	        let mut c = self
116	            .shared
117	            .control
118	            .lock()
119	            .unwrap_or_else(|e| e.into_inner());
120	        // Only dispatch fills this slot, immediately after taking a completion
121	        // which checked it empty. The worker can only empty it in between.
122	        assert!(c.retired.is_none());
123	        c.retired = Some(value);
124	        self.shared.changed.notify_one();
125	    }
126	    pub fn shutdown(&mut self) -> std::io::Result<()> {
127	        {
128	            let mut c = self
129	                .shared
130	                .control
131	                .lock()
132	                .unwrap_or_else(|e| e.into_inner());
133	            c.closed = true;
134	            self.shared.changed.notify_one();
135	        }
136	        if let Some(worker) = self.worker.take() {
137	            worker
138	                .join()
139	                .map_err(|_| std::io::Error::other("configuration preparation worker panicked"))?;
140	        }
141	        Ok(())
142	    }
143	    pub fn diagnostics(&self) -> serde_json::Value {
144	        let c = self
145	            .shared
146	            .control
147	            .lock()
148	            .unwrap_or_else(|e| e.into_inner());
149	        serde_json::json!({
150	            "requested_generation":(c.latest != 0).then(||c.latest.to_string()),
151	            "applied_generation":self.applied.map(|g|g.to_string()),
152	            "prepared_generation":c.completion.as_ref().filter(|(g,r)|*g == c.latest && r.is_ok()).map(|(g,_)|g.to_string()),
153	            "status":self.status, "last_error":self.last_error,
154	        })
155	    }
156	    pub fn applied(&self) -> bool {
157	        self.applied.is_some()
158	    }
159	}
160	impl Drop for RuntimeConfig {
161	    fn drop(&mut self) {
162	        let _ = self.shutdown();
163	    }
164	}
165	fn resolve_default_width(
166	    layout: &flux_config::Layout,
167	) -> Result<flux_layout::WidthPolicy, Failure> {
168	    let width = match &layout.default_width {
169	        flux_config::Width::Preset { preset } => layout
170	            .width_presets
171	            .get(
172	                preset
173	                    .checked_sub(1)
174	                    .ok_or("default width preset is invalid")?,
175	            )
176	            .ok_or("default width preset is invalid")?,
177	        width => width,
178	    };
179	    match width {
180	        flux_config::Width::Pixels { logical_px } => {
181	            Ok(flux_layout::WidthPolicy::Fixed(*logical_px))
182	        }
183	        flux_config::Width::Fraction { fraction } => {
184	            Ok(flux_layout::WidthPolicy::ViewportFraction(*fraction))
185	        }
186	        flux_config::Width::Preset { .. } => Err("default width preset is recursive"),
187	    }
188	}
189	fn width_value(width: flux_layout::WidthPolicy) -> serde_json::Value {
190	    match width {
191	        flux_layout::WidthPolicy::Fixed(logical_px) => serde_json::json!({"logical_px":logical_px}),
192	        flux_layout::WidthPolicy::ViewportFraction(fraction) => {
193	            serde_json::json!({"fraction":fraction})
194	        }
195	    }
196	}
197	
198	fn run_worker(
199	    shared: Arc<Shared>,
200	    mut coordinator: ConfigCoordinator,
201	    keymap: String,
202	    ping: calloop::ping::Ping,
203	) {
204	    let context = xkb::Context::new(xkb::CONTEXT_NO_ENVIRONMENT_NAMES);
205	    let map = xkb::Keymap::new_from_string(
206	        &context,
207	        keymap,
208	        xkb::KEYMAP_FORMAT_TEXT_V1,
209	        xkb::KEYMAP_COMPILE_NO_FLAGS,
210	    );
211	    let mut active = None;
212	    loop {
213	        let (job, retired, ready) = {
214	            let mut c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
215	            while !c.closed && c.pending.is_none() && c.retired.is_none() && !c.evaluation_ready {
216	                c = shared.changed.wait(c).unwrap_or_else(|e| e.into_inner());
217	            }
218	            if c.closed {
219	                break;
220	            }
221	            let values = (c.pending.take(), c.retired.take(), c.evaluation_ready);
222	            c.evaluation_ready = false;
223	            values
224	        };
225	        let retired_any = retired.is_some();
226	        drop(retired);
227	        if retired_any {
228	            ping.ping();
229	        }
230	        if let Some((generation, path)) = job {
231	            // Move stale completions out before dropping them off dispatch.
232	            let old = shared
233	                .control
234	                .lock()
235	                .unwrap_or_else(|e| e.into_inner())
236	                .completion
237	                .take();
238	            drop(old);
239	            match coordinator.request_path(path) {
240	                Ok(inner) => active = Some((generation, inner)),
241	                Err(_) => publish(
242	                    &shared,
243	                    generation,
244	                    Err("configuration request could not be admitted"),
245	                    &ping,
246	                ),
247	            }
248	        }
249	        if ready
250	            && let Some(result) = coordinator.take_completion()
251	            && let Some((generation, inner)) = active
252	            && inner == result.generation
253	        {
254	            let result = result
255	                .result
256	                .map_err(|failure| match failure.kind {
257	                    flux_config::ConfigFailureKind::Io => {
258	                        "configuration source or helper I/O failed"
259	                    }
260	                    flux_config::ConfigFailureKind::Invalid => {
261	                        "configuration schema or source validation failed"
262	                    }
263	                    flux_config::ConfigFailureKind::Timeout => "configuration evaluation timed out",
264	                    flux_config::ConfigFailureKind::Helper => {
265	                        "configuration helper rejected evaluation"
266	                    }
267	                    flux_config::ConfigFailureKind::Cancelled => {
268	                        "configuration evaluation cancelled"
269	                    }
270	                })
271	                .and_then(|candidate| {
272	                    let config = &candidate.config().config;
273	                    if config.layout.gaps > 1024.0 {
274	                        return Err("layout.gaps exceeds the nested model limit of 1024");
275	                    }
276	                    if config.bindings.iter().any(|b| {
277	                        matches!(
278	                            b.action,
279	                            flux_core::Action::Fullscreen { .. }
280	                                | flux_core::Action::Floating { .. }
281	                                | flux_core::Action::Overview { .. }
282	                                | flux_core::Action::Lock
283	                        )
284	                    }) {
285	                        return Err("a binding action is unavailable in the nested backend");
286	                    }
287	                    let bindings = BindingSet::compile(
288	                        &config.bindings,
289	                        map.as_ref()
290	                            .ok_or("seat keymap could not be reconstructed")?,
291	                        UnmappedPolicy::Reject,
292	                    )
293	                    .map_err(|_| "configuration bindings failed seat-keymap validation")?;
294	                    Ok(Prepared {
295	                        default_width: resolve_default_width(&config.layout)?,
296	                        desired: config.clone(),
297	                        bindings,
298	                    })
299	                });
300	            publish(&shared, generation, result, &ping);
301	        }
302	    }
303	    // No join or large source/schema/table destruction runs during dispatch.
304	    let _ = coordinator.shutdown();
305	    let mut c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
306	    c.pending = None;
307	    c.completion = None;
308	    c.retired = None;
309	}
310	fn publish(
311	    shared: &Shared,
312	    generation: u64,
313	    value: Result<Prepared, Failure>,
314	    ping: &calloop::ping::Ping,
315	) {
316	    let old = {
317	        let mut c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
318	        if c.closed || c.latest != generation {
319	            return;
320	        }
321	        c.completion.replace((generation, value))
322	    };
323	    drop(old);
324	    ping.ping();
325	}
326	
327	impl crate::Fluxwm {
328	    pub fn init_config(
329	        &mut self,
330	        handle: &calloop::LoopHandle<'static, Self>,
331	        source: Option<PathBuf>,
332	        helper: PathBuf,
333	    ) -> std::io::Result<()> {
334	        let Some(source) = source else {
335	            return Ok(());
336	        };
337	        let (ping, events) = calloop::ping::make_ping()?;
338	        handle
339	            .insert_source(events, |(), _, _| {})
340	            .map_err(|e| std::io::Error::other(e.to_string()))?;
341	        let keyboard = self.seat.get_keyboard().expect("startup seat has keyboard");
342	        let keymap = keyboard.with_xkb_state(self, |context| {
343	            let xkb = context.xkb().lock().unwrap();
344	            // SAFETY: string serialization borrows only under this Xkb lock;
345	            // the worker receives owned bytes and creates its own native map.
346	            unsafe { xkb.keymap() }.get_as_string(xkb::KEYMAP_FORMAT_TEXT_V1)
347	        });
348	        let mut config = RuntimeConfig::new(source, helper, keymap, ping)?;
349	        config.request().map_err(std::io::Error::other)?;
350	        self.config = Some(config);
351	        Ok(())
352	    }
353	    pub fn request_config_reload(&mut self) -> Result<u64, Failure> {
354	        if self.stopping || self.shutdown_deadline.is_some() {
355	            return Err("instance is shutting down");
356	        }
357	        self.config
358	            .as_mut()
359	            .ok_or("configuration loading is disabled")?
360	            .request()
361	    }
362	    pub fn drive_config(&mut self) {
363	        if self.stopping
364	            || self.shutdown_deadline.is_some()
365	            || self
366	                .seat
367	                .get_keyboard()
368	                .is_some_and(|k| !k.pressed_keys().is_empty() || k.is_grabbed())
369	            || self.seat.get_pointer().is_some_and(|p| p.is_grabbed())
370	            || !self.pointer_presses.is_empty()
371	        {
372	            return;
373	        }
374	        let Some(mut config) = self.config.take() else {
375	            return;
376	        };
377	        if let Some((generation, result)) = config.completion() {
378	            match result {
379	                Err(error) => {
380	                    config.status = "failed";
381	                    config.last_error = Some(error);
382	                    self.bump_sequence();
383	                }
384	                Ok(prepared) => {
385	                    let mut layout = self.layout.clone();
386	                    if layout
387	                        .reconfigure_with_default_width(
388	                            prepared.desired.layout.gaps,
389	                            prepared.desired.layout.mode,
390	                            prepared.default_width,
391	                        )
392	                        .is_err()
393	                    {
394	                        config.status = "failed";
395	                        config.last_error =
396	                            Some("configuration layout would invalidate live geometry");
397	                        config.retire(Retired {
398	                            _desired: Some(prepared.desired),
399	                            _bindings: Some(prepared.bindings),
400	                            _layout: Some(layout),
401	                        });
402	                    } else if self.sequence == u64::MAX {
403	                        config.status = "failed";
404	                        config.last_error = Some("state sequence exhausted");
405	                        config.retire(Retired {
406	                            _desired: Some(prepared.desired),
407	                            _bindings: Some(prepared.bindings),
408	                            _layout: Some(layout),
409	                        });
410	                    } else {
411	                        let old = Retired {
412	                            _desired: config.desired.replace(prepared.desired),
413	                            _bindings: Some(std::mem::replace(
414	                                &mut self.bindings,
415	                                prepared.bindings,
416	                            )),
417	                            _layout: Some(std::mem::replace(&mut self.layout, layout)),
418	                        };
419	                        config.applied = Some(generation);
420	                        config.status = "applied";
421	                        config.last_error = None;
422	                        config.retire(old);
423	                        self.relayout();
424	                        self.restore_keyboard_focus();
425	                    }
426	                    self.bump_sequence();
427	                }
428	            }
429	        }
430	        self.config = Some(config);
431	    }
432	    pub fn effective_config(&self) -> serde_json::Value {
433	        let config = self.config.as_ref();
434	        serde_json::json!({
435	            "generation":config.and_then(|c|c.applied).map(|g|g.to_string()),
436	            "desired":config.and_then(|c|c.desired.as_ref()).map(|c|serde_json::json!({"layout":{"gaps":c.layout.gaps,"mode":c.layout.mode,"default_width":c.layout.default_width,"width_presets":c.layout.width_presets},"binding_entries":c.bindings.len()})),
437	            "effective":{"layout":{"gaps":self.layout.gap(),"mode":self.layout.mode(),"default_width":width_value(self.layout.default_width())},"binding_entries":self.bindings.len(),"keymap":"startup-seat-keymap"},
438	            "unsupported":["layout.outer_gap","layout.focus_margin","layout.canvas","input","outputs","animations","decoration","rules","autostart","security"],
439	        })
440	    }
441	}
