266	impl Serialize for Color {
267	    fn serialize<S: serde::Serializer>(&self, s: S) -> std::result::Result<S::Ok, S::Error> {
268	        s.serialize_str(&format!(
269	            "#{:02X}{:02X}{:02X}{:02X}",
