274	impl<'de> Deserialize<'de> for Color {
275	    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> std::result::Result<Self, D::Error> {
276	        let s = String::deserialize(d)?;
277	        if !matches!(s.len(), 7 | 9)
278	            || !s.starts_with('#')
279	            || !s.as_bytes()[1..].iter().all(u8::is_ascii_hexdigit)
280	        {
281	            return Err(serde::de::Error::custom(
282	                "expected sRGB #RRGGBB or #RRGGBBAA",
283	            ));
284	        }
285	        let mut c = [255; 4];
286	        for (i, v) in c.iter_mut().enumerate().take((s.len() - 1) / 2) {
287	            *v = u8::from_str_radix(&s[1 + i * 2..3 + i * 2], 16)
288	                .map_err(serde::de::Error::custom)?;
289	        }
290	        Ok(Self(c))
291	    }
