437	fn range(v: f64, lo: f64, hi: f64, path: &str) -> Result<()> {
438	    if !v.is_finite() || v < lo || v > hi {
439	        return Err(invalid(format!(
440	            "{path}: expected finite number in {lo}..={hi}"
441	        )));
442	    }
443	    Ok(())
444	}
445	fn text(s: &str, path: &str, empty: bool) -> Result<()> {
446	    if (!empty && s.is_empty()) || s.len() > 4096 || s.contains('\0') {
447	        return Err(invalid(format!(
448	            "{path}: empty, oversized, or NUL-containing string"
449	        )));
450	    }
451	    Ok(())
452	}
453	fn argv(a: &[String], path: &str) -> Result<()> {
454	    flux_core::validate_argv(a).map_err(|error| invalid(format!("{path}: {error}")))
455	}
456	
457	fn pattern(p: &Option<String>, path: &str, engine_limit: usize) -> Result<Option<Regex>> {
458	    p.as_ref()
459	        .map(|s| {
460	            text(s, path, true)?;
461	            RegexBuilder::new(s)
462	                .size_limit(engine_limit)
463	                .dfa_size_limit(engine_limit)
464	                .nest_limit(64)
465	                .build()
466	                .map_err(|e| invalid(format!("{path}: {e}")))
467	        })
468	        .transpose()
469	}
470	fn width(w: &Width, n: usize, allow_preset: bool, path: &str) -> Result<()> {
471	    match w {
472	        Width::Pixels { logical_px } => range(*logical_px, 1., 65536., path),
473	        Width::Fraction { fraction } => range(*fraction, 0.01, 16., path),
474	        Width::Preset { preset } if allow_preset && *preset > 0 && *preset <= n => Ok(()),
475	        _ => Err(invalid(format!(
476	            "{path}: invalid or recursive width preset"
477	        ))),
478	    }
479	}
480	impl Key {
481	    /// Deterministic chord normalization. Actual keysym/keymap resolution is a backend gate.
482	    pub fn identity(&self) -> Result<String> {
483	        fn mods(parts: impl Iterator<Item = String>) -> Result<String> {
484	            let mut out = BTreeSet::new();
485	            for p in parts {
486	                if !matches!(p.as_str(), "Super" | "Alt" | "Ctrl" | "Shift" | "Logo") {
487	                    return Err(invalid(format!("key: unknown modifier {p}")));
488	                }
489	                let p = if p == "Logo" { "Super".to_string() } else { p };
490	                if !out.insert(p) {
491	                    return Err(invalid("key: duplicate modifier"));
492	                }
493	            }
494	            Ok(out.into_iter().collect::<Vec<_>>().join("+"))
495	        }
496	        match self {
497	            Key::Sym { sym } => {
498	                text(sym, "key.sym", false)?;
499	                let mut p = sym.split('+').collect::<Vec<_>>();
500	                let key = p.pop().unwrap();
501	                if key.is_empty()
502	                    || !key.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_')
503	                    || key.len() == 1 && key.as_bytes()[0].is_ascii_uppercase()
504	                {
505	                    return Err(invalid(
506	                        "key.sym: use canonical keysym names and lowercase letters",
507	                    ));
508	                }
509	                Ok(format!(
510	                    "sym:{}:{key}",
511	                    mods(p.into_iter().map(str::to_owned))?
512	                ))
513	            }
514	            Key::Code { code, modifiers } => {
515	                if !(1..=767).contains(code) {
516	                    return Err(invalid("key.code: expected evdev code 1..=767"));
517	                }
518	                Ok(format!("code:{}:{code}", mods(modifiers.iter().cloned())?))
519	            }
520	        }
521	    }
522	}
523	impl Config {
524	    /// Parse bounded normalized JSON using the same schema as helper output, with field paths.
525	    pub fn from_json(bytes: &[u8]) -> Result<Self> {
526	        if bytes.len() > 4 * 1024 * 1024 {
527	            return Err(invalid("config result exceeds 4 MiB"));
528	        }
529	        crate::bounds::preflight(bytes)?;
530	        let mut de = serde_json::Deserializer::from_slice(bytes);
531	        let value = serde_path_to_error::deserialize(&mut de)
532	            .map_err(|e| invalid(format!("{}: {}", e.path(), e.inner())))?;
533	        de.end().map_err(|e| invalid(e.to_string()))?;
534	        Ok(value)
535	    }
536	    /// Validates all schema values and compiles bounded non-backtracking rule patterns.
537	    pub fn validate(&self) -> Result<CompiledConfig> {
538	        if self.schema_version != 1 {
539	            return Err(invalid("schema_version: only version 1 is supported"));
540	        }
541	        let l = &self.layout;
542	        for (v, p) in [
543	            (l.gaps, "layout.gaps"),
544	            (l.outer_gap, "layout.outer_gap"),
545	            (l.focus_margin, "layout.focus_margin"),
546	        ] {
547	            range(v, 0., 4096., p)?;
548	        }
549	        if l.width_presets.is_empty() || l.width_presets.len() > 128 {
550	            return Err(invalid("layout.width_presets: expected 1..=128 widths"));
551	        }
552	        for w in &l.width_presets {
553	            width(w, l.width_presets.len(), false, "layout.width_presets")?;
554	        }
555	        width(
556	            &l.default_width,
557	            l.width_presets.len(),
558	            true,
559	            "layout.default_width",
560	        )?;
561	        range(
562	            l.canvas.snap_distance_physical_px,
563	            0.,
564	            512.,
565	            "layout.canvas.snap_distance_physical_px",
566	        )?;
567	        text(&self.input.keymap.layout, "input.keymap.layout", false)?;
568	        text(&self.input.keymap.options, "input.keymap.options", true)?;
569	        range(
570	            self.input.pointer.acceleration,
571	            -1.,
572	            1.,
573	            "input.pointer.acceleration",
574	        )?;
575	        for n in [
576	            self.input.gestures.pan_fingers,
577	            self.input.gestures.overview_fingers,
578	        ] {
579	            if !(2..=5).contains(&n) {
580	                return Err(invalid("input.gestures: finger count must be 2..=5"));
581	            }
582	        }
583	        if self.outputs.len() > 128 {
584	            return Err(invalid("outputs: maximum 128 rules"));
585	        }
586	        for (i, o) in self.outputs.iter().enumerate() {
587	            let p = format!("outputs[{i}]");
588	            match &o.matcher {
589	                OutputMatch::Any { any: true } => (),
590	                OutputMatch::Any { any: false } => {
591	                    return Err(invalid(format!("{p}.match.any: must be true")));
592	                }
593	                OutputMatch::Fields {
594	                    connector,
595	                    make,
596	                    model,
597	                    serial,
598	                } => {
599	                    let values = [connector, make, model, serial];
600	                    if values.iter().all(|v| v.is_none()) {
601	                        return Err(invalid(format!("{p}.match: empty selector")));
602	                    }
603	                    for s in values.into_iter().flatten() {
604	                        text(s, &p, false)?;
605	                    }
606	                }
607	            }
608	            if let Some(s) = o.scale {
609	                range(s, 0.25, 8., &format!("{p}.scale"))?;
610	            }
611	        }
612	        let a = &self.animations;
613	        if a.curves.len() > 128 {
614	            return Err(invalid("animations.curves: maximum 128 curves"));
615	        }
616	        for (name, c) in &a.curves {
617	            text(name, "animations.curves name", false)?;
618	            match c {
619	                Curve::Spring {
620	                    mass,
621	                    stiffness,
622	                    damping,
623	                } => {
624	                    range(*mass, 0.001, 100., "spring.mass")?;
625	                    range(*stiffness, 0.001, 100000., "spring.stiffness")?;
626	                    range(*damping, 0., 100000., "spring.damping")?;
627	                }
628	                Curve::Bezier { points } => {
629	                    for (i, p) in points.iter().enumerate() {
630	                        range(
631	                            *p,
632	                            if i % 2 == 0 { 0. } else { -4. },
633	                            if i % 2 == 0 { 1. } else { 4. },
634	                            "bezier.points",
635	                        )?;
636	                    }
637	                }
638	            }
639	        }
640	        for (p, t) in [
641	            ("camera", &a.camera),
642	            ("window", &a.window),
643	            ("fade", &a.fade),
644	        ] {
645	            if !a.curves.contains_key(&t.curve) {
646	                return Err(invalid(format!(
647	                    "animations.{p}.curve: unknown curve {}",
648	                    t.curve
649	                )));
650	            }
651	            if let Some(d) = t.duration_ms {
652	                range(d, 0., 10000., &format!("animations.{p}.duration_ms"))?;
653	            }
654	            if matches!(a.curves.get(&t.curve), Some(Curve::Bezier { .. }))
655	                && t.duration_ms.is_none()
656	            {
657	                return Err(invalid(format!(
658	                    "animations.{p}.duration_ms: required for bezier"
659	                )));
660	            }
661	        }
662	        let d = &self.decoration;
663	        for (v, p, max) in [
664	            (d.border.width, "decoration.border.width", 64.),
665	            (d.corner_radius, "decoration.corner_radius", 512.),
666	            (d.shadow.radius, "decoration.shadow.radius", 512.),
667	            (d.blur.radius, "decoration.blur.radius", 64.),
668	            (d.shadow.opacity, "decoration.shadow.opacity", 1.),
669	        ] {
670	            range(v, 0., max, p)?;
671	        }
672	        if !(1..=8).contains(&d.blur.passes) {
673	            return Err(invalid("decoration.blur.passes: expected 1..=8"));
674	        }
675	        if self.bindings.len() > 4096 {
676	            return Err(invalid("bindings: maximum 4096"));
677	        }
678	        let mut ids = BTreeSet::new();
679	        let mut binding_identities = Vec::new();
680	        for (i, b) in self.bindings.iter().enumerate() {
681	            let id = b.key.identity()?;
682	            if !ids.insert(id.clone()) {
683	                return Err(invalid(format!(
684	                    "bindings[{i}]: duplicate normalized chord {id}"
685	                )));
686	            }
687	            binding_identities.push(id);
688	            b.action
689	                .validate()
690	                .map_err(|error| invalid(format!("bindings[{i}].action: {error}")))?;
691	        }
692	        if self.rules.len() > 1024 {
693	            return Err(invalid("rules: maximum 1024"));
694	        }
695	        // Allocate a shared engine-size budget across every pattern before any
696	        // compilation. Limits concern regex engine accounting, not exact RSS.
697	        let pattern_count = self
698	            .rules
699	            .iter()
700	            .map(|r| {
701	                usize::from(r.matcher.app_id.is_some()) + usize::from(r.matcher.title.is_some())
702	            })
703	            .sum::<usize>();
704	        let engine_limit = (32 * 1024 * 1024 / pattern_count.max(1)).min(1024 * 1024);
705	        let mut rules = Vec::new();
706	        for (i, r) in self.rules.iter().enumerate() {
707	            if r.matcher.app_id.is_none()
708	                && r.matcher.title.is_none()
709	                && r.matcher.is_dialog.is_none()
710	            {
711	                return Err(invalid(format!("rules[{i}].match: empty matcher")));
712	            }
713	            rules.push(CompiledRule {
714	                app_id: pattern(
715	                    &r.matcher.app_id,
716	                    &format!("rules[{i}].match.app_id"),
717	                    engine_limit,
718	                )?,
719	                title: pattern(
720	                    &r.matcher.title,
721	                    &format!("rules[{i}].match.title"),
722	                    engine_limit,
723	                )?,
724	                is_dialog: r.matcher.is_dialog,
725	                set: r.set.clone(),
726	                dynamic: r.dynamic,
727	            });
728	        }
729	        if self.autostart.len() > 128 {
730	            return Err(invalid("autostart: maximum 128 commands"));
731	        }
732	        for (i, a) in self.autostart.iter().enumerate() {
733	            argv(&a.argv, &format!("autostart[{i}].argv"))?;
734	        }
735	        Ok(CompiledConfig {
736	            config: self.clone(),
737	            rules,
738	            binding_identities,
739	        })
740	    }
741	    pub fn output_settings(
742	        &self,
743	        connector: &str,
744	        make: &str,
745	        model: &str,
746	        serial: &str,
747	    ) -> OutputSettings {
748	        let mut settings = OutputSettings::default();
749	        for o in &self.outputs {
750	            let matches = match &o.matcher {
751	                OutputMatch::Any { any } => *any,
752	                OutputMatch::Fields {
753	                    connector: c,
754	                    make: m,
755	                    model: mo,
756	                    serial: s,
757	                } => {
758	                    c.as_deref().is_none_or(|v| v == connector)
759	                        && m.as_deref().is_none_or(|v| v == make)
760	                        && mo.as_deref().is_none_or(|v| v == model)
761	                        && s.as_deref().is_none_or(|v| v == serial)
762	                }
763	            };
764	            if matches {
765	                if let Some(scale) = o.scale {
766	                    settings.scale = Some(scale);
767	                }
768	                if let Some(a) = o.adaptive_sync {
769	                    settings.adaptive_sync = Some(a);
770	                }
771	            }
772	        }
773	        settings
774	    }
775	}
776	impl CompiledConfig {
777	    /// Every metadata update must re-evaluate privacy before capture admission.
778	    /// This returns eligibility only, never capture authority; deny remains sticky.
779	    pub fn evaluate_rules(
780	        &self,
781	        app_id: &str,
782	        title: &str,
783	        is_dialog: bool,
784	        sticky_deny: bool,
785	    ) -> RuleSet {
786	        let mut result = RuleSet::default();
787	        let mut deny = sticky_deny;
788	        for r in &self.rules {
789	            if r.app_id.as_ref().is_some_and(|p| !p.is_match(app_id))
790	                || r.title.as_ref().is_some_and(|p| !p.is_match(title))
791	                || r.is_dialog.is_some_and(|v| v != is_dialog)
792	            {
793	                continue;
794	            }
795	            if let Some(v) = r.set.floating {
796	                result.floating = Some(v);
797	            }
798	            if let Some(v) = r.set.center_on_parent {
799	                result.center_on_parent = Some(v);
800	            }
801	            if let Some(v) = r.set.capture {
802	                deny |= v == CapturePolicy::Deny;
803	                result.capture = Some(v);
804	            }
805	        }
806	        if deny {
807	            result.capture = Some(CapturePolicy::Deny);
808	        }
809	        result
810	    }
811	}
