2937	/// Layout rejection must not confuse protocol buffer ownership with scene
2938	/// membership. Keep the client alive so it can unmap and retry smaller hints.
2939	fn config_width(timeout: Duration) -> Json {
2940	    let start = Instant::now();
2941	    let deadline = start + timeout;
2942	    let mut state = State::new(start);
2943	    let mut evidence = json!({"ok":false,"mode":"config-width"});
2944	    let result = (|| -> Result<()> {
2945	        let connection = connect(&display_path()?, deadline)?;
2946	        let mut queue = connection.new_event_queue::<State>();
2947	        let qh = queue.handle();
2948	        health_registry(&connection, &mut queue, &mut state, deadline)?;
2949	        let ipc = std::env::var_os("FLUXWM_SOCKET").ok_or("explicit IPC socket required")?;
2950	        let mut diagnostics = Diagnostics::new(Path::new(&ipc), deadline)?;
2951	        for (index, expected) in [
2952	            json!({"logical_px":400.0}),
2953	            json!({"logical_px":760.0}),
2954	            json!({"fraction":0.25}),
2955	            json!({"logical_px":600.0}),
2956	            json!({"logical_px":600.0}),
2957	            json!({"logical_px":480.0}),
2958	        ]
2959	        .into_iter()
2960	        .enumerate()
2961	        {
2962	            loop {
2963	                let effective = diagnostics.call("config.effective", json!({}), deadline)?;
2964	                let status = diagnostics.call("diagnostics", json!({}), deadline)?;
